shadow_bundle.shadow_css:
:host { display: block; width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }
.wsj-shadow-body { width: 100%; max-width: 100%; overflow-x: clip; box-sizing: border-box; }

  :host {
    --paper: #faf8f4;
    --paper-card: #f3efe6;
    --paper-deep: #ece6d9;
    --ink: #141413;
    --body: #242220;
    --muted: #646059;
    --line: #e4dfd3;
    --line-strong: #c9c2b2;
    --accent: #b85d19;
    --accent-soft: rgba(184, 93, 25, 0.12);
    --navy-bg: #0f1d2b;
    --navy-card: #16283a;
    --navy-line: #283e54;
    --slate-blue: #23496d;
    --crimson: #9e2a2b;
    --crimson-soft: rgba(158, 42, 43, 0.1);
    --forest: #2b593f;
    --gold: #c98a27;

    --font-display: 'Playfair Display', 'Noto Serif SC', Georgia, serif;
    --font-serif-cn: 'Noto Serif SC', 'Source Han Serif SC', serif;
    --font-serif-en: 'Lora', Georgia, serif;
    --font-sans: 'Inter', 'Noto Sans SC', -apple-system, BlinkMacSystemFont, sans-serif;
    --font-mono: 'JetBrains Mono', monospace;
  }

  * {
    box-sizing: border-box;
    margin: 0;
    padding: 0;
  }

  html {
    background-color: var(--paper);
    color: var(--body);
    font-size: 16px;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    scroll-behavior: smooth;
  }

  .wsj-shadow-body {
    background-color: var(--paper);
    overflow-x: hidden;
    width: 100%;
    position: relative;
  }

  /* Strict Bilingual Toggle Visibility */
  :host([lang="zh-CN"]) .lang-en { display: none !important; }
  :host([lang="en"]) .lang-cn { display: none !important; }

  /* Sticky Top Masthead */
  .masthead {
    position: sticky;
    top: 0;
    z-index: 1000;
    background: rgba(250, 248, 244, 0.94);
    backdrop-filter: blur(10px);
    -webkit-backdrop-filter: blur(10px);
    border-bottom: 1px solid var(--line-strong);
    height: 54px;
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 0 24px;
  }

  .masthead-brand {
    display: flex;
    align-items: center;
    gap: 12px;
  }

  .wsj-logo {
    font-family: var(--font-display);
    font-weight: 800;
    font-size: 1.05rem;
    letter-spacing: 0.06em;
    color: var(--ink);
    text-transform: uppercase;
  }

  .wsj-divider {
    width: 1px;
    height: 16px;
    background: var(--line-strong);
  }

  .wsj-rubric {
    font-family: var(--font-sans);
    font-size: 0.75rem;
    font-weight: 600;
    letter-spacing: 0.08em;
    text-transform: uppercase;
    color: var(--accent);
  }

  .masthead-controls {
    display: flex;
    align-items: center;
    gap: 16px;
  }

  .edition-badge {
    font-family: var(--font-mono);
    font-size: 0.7rem;
    color: var(--muted);
    letter-spacing: 0.04em;
    display: none;
  }

  @media (min-width: 768px) {
    .edition-badge {
      display: inline-block;
    }
  }

  .lang-switch {
    display: inline-flex;
    background: var(--paper-deep);
    border: 1px solid var(--line-strong);
    border-radius: 4px;
    padding: 2px;
    gap: 2px;
  }

  .lang-btn {
    border: none;
    background: transparent;
    font-family: var(--font-sans);
    font-size: 0.75rem;
    font-weight: 600;
    padding: 4px 10px;
    border-radius: 2px;
    cursor: pointer;
    color: var(--muted);
    transition: all 0.18s ease;
  }

  .lang-btn.active {
    background: var(--ink);
    color: var(--paper);
  }

  /* Main Container */
  .page-shell {
    max-width: 1240px;
    margin: 0 auto;
    padding: 0 24px;
  }

  /* Hero Header */
  .hero-header {
    padding: 56px 0 40px;
    border-bottom: 3px double var(--ink);
    margin-bottom: 40px;
  }

  .hero-kicker-row {
    display: flex;
    flex-wrap: wrap;
    align-items: center;
    gap: 12px;
    margin-bottom: 20px;
  }

  .hero-kicker {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--paper);
    background: var(--accent);
    padding: 4px 10px;
  }

  .hero-series {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    font-weight: 500;
    color: var(--muted);
    letter-spacing: 0.05em;
  }

  .hero-title {
    font-family: var(--font-display);
    font-size: clamp(2.15rem, 4.4vw, 3.85rem);
    font-weight: 800;
    line-height: 1.15;
    color: var(--ink);
    letter-spacing: -0.015em;
    margin-bottom: 18px;
    max-width: 960px;
  }

  :host([lang="zh-CN"]) .hero-title {
    line-height: 1.24;
    letter-spacing: 0.01em;
  }

  .hero-dek {
    font-family: var(--font-serif-en);
    font-size: clamp(1.15rem, 2vw, 1.5rem);
    font-weight: 400;
    line-height: 1.48;
    color: var(--muted);
    max-width: 820px;
    margin-bottom: 32px;
  }

  :host([lang="zh-CN"]) .hero-dek {
    font-family: var(--font-serif-cn);
    line-height: 1.65;
  }

  .hero-meta-bar {
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    align-items: flex-end;
    padding-top: 20px;
    border-top: 1px solid var(--line);
    gap: 16px;
  }

  .byline-block {
    font-family: var(--font-sans);
    font-size: 0.85rem;
    color: var(--body);
  }

  .byline-author {
    font-weight: 700;
    color: var(--ink);
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  .byline-date {
    font-family: var(--font-mono);
    font-size: 0.78rem;
    color: var(--muted);
    margin-left: 12px;
  }

  /* Hero Key Ledger Strip */
  .hero-ledger-strip {
    display: grid;
    grid-template-columns: repeat(4, 1fr);
    gap: 1px;
    background: var(--line-strong);
    border: 1px solid var(--line-strong);
    margin-bottom: 48px;
  }

  .ledger-cell {
    background: var(--paper-card);
    padding: 18px 20px;
    display: flex;
    flex-direction: column;
    justify-content: space-between;
  }

  .ledger-cell .metric-val {
    font-family: var(--font-mono);
    font-size: 1.6rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.1;
    margin-bottom: 6px;
  }

  .ledger-cell.highlight-cell .metric-val {
    color: var(--accent);
  }

  .ledger-cell .metric-lbl {
    font-family: var(--font-sans);
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 4px;
    line-height: 1.35;
  }

  .ledger-cell .metric-note {
    font-family: var(--font-sans);
    font-size: 0.72rem;
    color: var(--muted);
    line-height: 1.4;
  }

  /* Typography for Prose */
  .prose-p {
    margin-bottom: 1.55rem;
    color: var(--body);
  }

  :host([lang="zh-CN"]) .prose-p {
    font-family: var(--font-serif-cn);
    font-size: 1.125rem;
    line-height: 1.92;
    letter-spacing: 0.015em;
  }

  :host([lang="en"]) .prose-p {
    font-family: var(--font-serif-en);
    font-size: 1.125rem;
    line-height: 1.8;
  }

  /* Lead Paragraph Stature (NO Chinese ::first-letter drop-cap) */
  .prose-p.lead-paragraph {
    font-size: 1.28rem !important;
    line-height: 1.78 !important;
    font-weight: 600;
    color: var(--ink);
    border-left: 3px solid var(--accent);
    padding-left: 18px;
    margin-bottom: 1.8rem;
  }

  /* Inline Highlight Mark */
  mark.ed-hl {
    background: linear-gradient(180deg, transparent 58%, rgba(184, 93, 25, 0.22) 58%);
    color: inherit;
    padding: 0 2px;
    font-weight: 600;
  }

  /* Section & Chapter Architecture */
  .editorial-section {
    margin-bottom: 64px;
  }

  .section-grid-2col {
    display: grid;
    grid-template-columns: minmax(0, 680px) minmax(280px, 380px);
    gap: 56px;
    justify-content: space-between;
    align-items: start;
  }

  .prose-column {
    width: 100%;
  }

  .side-rail {
    position: sticky;
    top: 78px;
    display: flex;
    flex-direction: column;
    gap: 24px;
  }

  /* Chapter Headers */
  .chapter-banner {
    border-top: 2px solid var(--ink);
    padding-top: 16px;
    margin-bottom: 32px;
    display: flex;
    align-items: baseline;
    justify-content: space-between;
    gap: 16px;
  }

  .chapter-num {
    font-family: var(--font-mono);
    font-size: 0.8rem;
    font-weight: 700;
    color: var(--accent);
    text-transform: uppercase;
    letter-spacing: 0.1em;
  }

  .chapter-title {
    font-family: var(--font-display);
    font-size: 1.55rem;
    font-weight: 700;
    color: var(--ink);
    flex: 1;
  }

  /* Dossier Card (Context ctx1) */
  .dossier-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    border-top: 3px solid var(--ink);
    padding: 22px 24px;
  }

  .dossier-kicker {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.09em;
    color: var(--accent);
    margin-bottom: 10px;
    display: flex;
    align-items: center;
    gap: 8px;
  }

  .dossier-kicker::before {
    content: "";
    display: inline-block;
    width: 7px;
    height: 7px;
    background: var(--accent);
  }

  .dossier-body {
    font-family: var(--font-sans);
    font-size: 0.88rem;
    line-height: 1.68;
    color: var(--body);
  }

  /* Pull Quote Styling */
  .pull-quote-card {
    background: var(--paper);
    border-top: 2px solid var(--accent);
    border-bottom: 1px solid var(--line-strong);
    padding: 20px 0;
    margin: 28px 0;
  }

  .pull-quote-card .quote-text {
    font-family: var(--font-display);
    font-size: 1.22rem;
    line-height: 1.52;
    color: var(--ink);
    font-weight: 700;
    margin-bottom: 12px;
  }

  .pull-quote-card .quote-attrib {
    font-family: var(--font-sans);
    font-size: 0.78rem;
    font-weight: 600;
    color: var(--muted);
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  /* Inline Quote Callout within narrative flow (p4) */
  .inline-spokesperson-box {
    background: var(--paper-card);
    border-left: 4px solid var(--ink);
    padding: 20px 24px;
    margin: 24px 0 32px;
  }

  .inline-spokesperson-box .prose-p {
    margin-bottom: 0.6rem;
  }

  .inline-spokesperson-box .prose-p:last-child {
    margin-bottom: 0;
    font-weight: 600;
    color: var(--ink);
  }

  /* SVG Exhibit Containers */
  .exhibit-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 24px;
    margin: 32px 0;
  }

  .exhibit-header {
    border-bottom: 1px solid var(--line-strong);
    padding-bottom: 12px;
    margin-bottom: 20px;
  }

  .exhibit-tag {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.08em;
    color: var(--accent);
    margin-bottom: 4px;
  }

  .exhibit-title {
    font-family: var(--font-display);
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--ink);
    line-height: 1.3;
    margin-bottom: 4px;
  }

  .exhibit-sub {
    font-family: var(--font-sans);
    font-size: 0.82rem;
    color: var(--muted);
    line-height: 1.45;
  }

  .exhibit-caption {
    font-family: var(--font-sans);
    font-size: 0.75rem;
    color: var(--muted);
    margin-top: 14px;
    padding-top: 12px;
    border-top: 1px solid var(--line);
    line-height: 1.45;
  }

  .svg-responsive {
    width: 100%;
    height: auto;
    display: block;
    overflow: visible;
  }

  /* Regulatory Alert Note (p7) */
  .regulatory-blot {
    background: var(--crimson-soft);
    border: 1px solid rgba(158, 42, 43, 0.3);
    border-left: 4px solid var(--crimson);
    padding: 18px 22px;
    margin: 28px 0;
  }

  .regulatory-blot-label {
    font-family: var(--font-mono);
    font-size: 0.72rem;
    font-weight: 700;
    color: var(--crimson);
    text-transform: uppercase;
    letter-spacing: 0.08em;
    margin-bottom: 6px;
  }

  .regulatory-blot .prose-p {
    margin-bottom: 0;
    font-size: 1.02rem !important;
  }

  /* Corporate Defense Dossier (p13 & p14) */
  .corporate-response-panel {
    background: var(--navy-bg);
    color: #f0ede6;
    padding: 28px 30px;
    margin: 36px 0;
    border-top: 4px solid var(--gold);
  }

  .corp-kicker {
    font-family: var(--font-mono);
    font-size: 0.74rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.1em;
    color: var(--gold);
    margin-bottom: 14px;
  }

  .corporate-response-panel .prose-p {
    color: #e6e2d8;
    font-size: 1.04rem !important;
    margin-bottom: 1.1rem;
  }

  .corporate-response-panel .prose-p:last-child {
    margin-bottom: 0;
    padding-top: 12px;
    border-top: 1px solid var(--navy-line);
  }

  .corporate-response-panel mark.ed-hl {
    background: rgba(201, 138, 39, 0.28);
    color: #fff;
  }

  /* Derived Metric Card in Side Rail */
  .rail-metric-card {
    background: var(--paper-card);
    border: 1px solid var(--line-strong);
    padding: 18px 20px;
  }

  .rail-metric-card .metric-val {
    font-family: var(--font-mono);
    font-size: 1.75rem;
    font-weight: 700;
    color: var(--accent);
    margin-bottom: 6px;
  }

  .rail-metric-card .metric-lbl {
    font-family: var(--font-sans);
    font-size: 0.84rem;
    font-weight: 700;
    color: var(--ink);
    margin-bottom: 4px;
  }

  .rail-metric-card .metric-note {
    font-family: var(--font-sans);
    font-size: 0.76rem;
    color: var(--muted);
    line-height: 1.45;
  }

  /* Climactic Verdict Box (p20) */
  .verdict-stage {
    background: var(--paper-card);
    border: 2px solid var(--ink);
    padding: 36px 32px;
    margin-top: 32px;
    position: relative;
  }

  .verdict-kicker {
    font-family: var(--font-mono);
    font-size: 0.75rem;
    font-weight: 700;
    text-transform: uppercase;
    letter-spacing: 0.12em;
    color: var(--accent);
    margin-bottom: 14px;
  }

  .verdict-quote {
    font-family: var(--font-display);
    font-size: clamp(1.35rem, 2.2vw, 1.75rem);
    font-weight: 700;
    line-height: 1.42;
    color: var(--ink);
  }

  /* Footer */
  .article-footer {
    border-top: 2px solid var(--ink);
    margin-top: 72px;
    padding: 32px 0 64px;
    display: flex;
    flex-wrap: wrap;
    justify-content: space-between;
    gap: 16px;
    font-family: var(--font-sans);
    font-size: 0.8rem;
    color: var(--muted);
  }

  /* Responsive Design for Tablet & Mobile (390px) */
  @media (max-width: 980px) {
    .hero-ledger-strip {
      grid-template-columns: repeat(2, 1fr);
    }

    .section-grid-2col {
      grid-template-columns: 1fr;
      gap: 32px;
    }

    .side-rail {
      position: static;
    }
  }

  @media (max-width: 560px) {
    .page-shell {
      padding: 0 16px;
    }

    .masthead {
      padding: 0 14px;
    }

    .wsj-rubric {
      display: none;
    }

    .hero-header {
      padding: 32px 0 28px;
    }

    .hero-ledger-strip {
      grid-template-columns: 1fr;
    }

    .exhibit-card {
      padding: 16px;
    }

    .corporate-response-panel {
      padding: 20px 18px;
    }

    .verdict-stage {
      padding: 24px 18px;
    }
  }
